import { Diagnostic, Project } from '../../src'

describe('Diagnostics', () => {
    test('should return a full diagnostic message, flattening any DiagnosticMessageChains in the ts.Diagnostic', async () => {
        const project = new Project()

        project.addFile({
            path: 'record.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({})`,
        })

        const diagnostics = (await project.getDiagnostics()).flatMap((d) => d.message.split('\n'))

        expect(diagnostics).toHaveLength(2)
        expect(diagnostics[0]).toContain(`Argument of type '{}' is not assignable to parameter of type`)
        expect(diagnostics[1]).toContain(`Property '$id' is missing in type '{}' but required in type`)
    })

    test('should simplify typescript diagnostic errors when mandatory table fields are missing in Record calls (with multiple fields missing)', async () => {
        const project = new Project()

        project.addFile({
            path: 'record.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'sp_widget',
    data: {}
})`,
        })

        const diagnostics = (await project.getDiagnostics())
            .filter((d) => d.level === Diagnostic.Level.Error)
            .map((d) => d.message)

        expect(diagnostics).toHaveLength(1)
        expect(diagnostics[0]).toContain(`Missing mandatory sp_widget fields: data_table, name`)
    })

    test('should simplify typescript diagnostic errors when mandatory table fields are missing in Record calls (with single field missing)', async () => {
        const project = new Project()

        project.addFile({
            path: 'record.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'sc_catalog',
    data: {}
})`,
        })

        const diagnostics = (await project.getDiagnostics())
            .filter((d) => d.level === Diagnostic.Level.Error)
            .map((d) => d.message)

        expect(diagnostics).toHaveLength(1)
        expect(diagnostics[0]).toContain(`Missing mandatory sc_catalog field: title`)
    })
})
